import glob, os
import pandas as pd
from collections import Counter

def read_fasta(p):
    with open(p) as f:
        cur, s = None, []
        for line in f:
            line = line.strip()
            if line.startswith(">"):
                if cur: yield cur, "".join(s)
                cur = line[1:]
                s = []
            else:
                s.append(line)
        if cur: yield cur, "".join(s)

all_derep = dict(read_fasta('/tmp/work/all_derep.fasta'))
seq_to_hdr = {s: h for h, s in all_derep.items()}

sample_files = sorted(glob.glob('/tmp/work/trimmed/*.fasta'))
samples = [os.path.basename(sf).replace('.fasta', '') for sf in sample_files]
sample_counts = {}
for sf, sname in zip(sample_files, samples):
    sample_counts[sname] = Counter(seq for h, seq in read_fasta(sf))

# For every sequence with total size >= 50, check its distribution across samples
candidates = []
for h, s in all_derep.items():
    sz = int(h.split('size=')[1])
    if sz >= 50:
        counts_per_sample = [sample_counts[sm].get(s, 0) for sm in samples]
        candidates.append((sz, h, s, counts_per_sample))

candidates.sort(key=lambda x: x[0], reverse=True)
print(f"Total candidates with size >= 50: {len(candidates)}")
print(f"{'Size':>5} | {'Samples > 0':>11} | Samples breakdown")
for sz, h, s, counts in candidates:
    present = [(sm, c) for sm, c in zip(samples, counts) if c > 0]
    pres_str = ", ".join(f"{sm}:{c}" for sm, c in present)
    print(f"{sz:5d} | {len(present):2d} samples | {pres_str}")
